d(r) as (select jsonb_array_elements($json$[{"k":"med-a-breakfast","f":"mediterranean","d":"A","m":"breakfast","n":"Feta, spinach and tomato scrambled eggs on sourdough","ds":"Soft scrambled eggs with salty feta, spinach and cherry tomatoes on toasted sourdough.","pr":5,"ck":8,"st":["Crack the eggs into a bowl with a pinch of pepper (no salt, the feta is salty) and whisk with a fork.","Halve the cherry tomatoes. Put the sourdough in the toaster.","Heat the olive oil in a non-stick frying pan over medium-low heat. Add the tomatoes and cook for 2 minutes, then add the spinach and stir until wilted.","Pour in the eggs. Wait 20 seconds, then slowly push the egg from the edges into the middle with a spatula.","When the eggs are almost set but still a little wet, crumble in the feta and sprinkle the oregano. Stir once and take the pan off the heat.","Spoon onto the toast and serve straight away."],"tp":"Rub a cut garlic clove over the hot toast for extra flavour.","dt":[],"c":446,"p":31.1,"cb":29.1,"ft":21.5,"ps":24,"i":[["Eggs",26,150,"3 eggs","egg",50],["Sourdough bread",85,60,"1 thick slice",null,null],["Feta, reduced fat",86,20,"2 tbsp crumbled",null,null],["Baby spinach",27,40,"1 large handful",null,null],["Cherry tomatoes",28,80,"6 to 8 tomatoes",null,null],["Olive oil",19,5,"1 tsp",null,null],["Dried oregano",21,0.5,"a pinch",null,null]]},{"k":"med-a-lunch","f":"mediterranean","d":"A","m":"lunch","n":"Chicken souvlaki pita with tzatziki","ds":"Lemon and oregano chicken in a warm pita with homemade tzatziki, tomato and onion.","pr":15,"ck":10,"st":["Cut the chicken into 3 cm cubes. In a bowl, mix with the olive oil, half the lemon juice, the oregano and a pinch of salt and pepper. Leave for 5 minutes (or up to a day in the fridge).","Make the tzatziki: grate half the cucumber, squeeze out the water with your hands, and mix it with the yoghurt, the rest of the lemon juice, the garlic (crushed) and a pinch of salt.","Thread the chicken onto skewers if you have them, or cook the pieces loose. Heat a frying pan or grill pan over medium-high heat and cook for 8 to 10 minutes, turning, until charred on the edges and cooked through.","Slice the tomato, the rest of the cucumber and the red onion. Shred the lettuce.","Warm the pita in the dry pan for 30 seconds each side so it is soft and bendy.","Spread the tzatziki over the pita, add the lettuce, tomato, cucumber, onion and chicken, and roll it up. Wrap the bottom in baking paper to hold it together."],"tp":"Soak wooden skewers in water for 10 minutes first so they do not burn.","dt":[],"c":445,"p":42.1,"cb":44.5,"ft":8.9,"ps":25,"i":[["Chicken breast",6,130,"1 small breast",null,null],["Pita bread",87,70,"1 large pita",null,null],["Greek yoghurt, low fat",2,60,"1/4 cup",null,null],["Cucumber",34,50,"1/3 cucumber",null,null],["Tomato",33,60,"1/2 tomato",null,null],["Red onion",73,20,"2 thin slices",null,null],["Cos lettuce",32,20,"1 leaf",null,null],["Olive oil",19,5,"1 tsp",null,null],["Lemon juice",36,10,"2 tsp",null,null],["Garlic",11,4,"1 small clove",null,null],["Dried oregano",21,1,"1/2 tsp",null,null]]},{"k":"med-a-dinner","f":"mediterranean","d":"A","m":"dinner","n":"Lamb kofta with tabouli and hummus","ds":"Spiced lamb kofta with a fresh parsley and bulgur tabouli and a spoon of hummus.","pr":20,"ck":12,"st":["Put the bulgur in a bowl and pour over 90 ml of boiling water. Cover with a plate and leave for 15 minutes until soft. Fluff with a fork.","Finely grate the onion. In another bowl, mix the lamb mince with the grated onion, cumin, coriander, a pinch of salt and pepper. Squish it together with clean hands for 1 minute.","Divide the mince into 4 and shape each piece into a sausage about 10 cm long. Push onto skewers if you like.","Heat a frying pan or grill over medium-high heat with a light brush of the olive oil. Cook the kofta for 8 to 10 minutes, turning every 2 minutes, until browned all over and cooked through.","While they cook, finely chop the parsley, tomato and cucumber. Mix them with the bulgur, the lemon juice, the rest of the olive oil and a pinch of salt. That is your tabouli.","Serve the kofta on the tabouli with the hummus on the side."],"tp":"Wet your hands before shaping the kofta so the mince does not stick.","dt":[],"c":499,"p":35.7,"cb":35.5,"ft":21.3,"ps":26,"i":[["Lean lamb mince",88,130,"130 g",null,null],["Bulgur (cracked wheat), dry",89,45,"1/4 cup",null,null],["Flat-leaf parsley",90,25,"1 big handful",null,null],["Tomato",33,80,"1 small tomato",null,null],["Cucumber",34,50,"1/3 cucumber",null,null],["Brown onion",17,30,"1/4 onion",null,null],["Hummus",91,30,"1 heaped tbsp",null,null],["Olive oil",19,5,"1 tsp",null,null],["Lemon juice",36,15,"1 tbsp",null,null],["Ground cumin",63,1,"1/2 tsp",null,null],["Ground coriander",92,1,"1/2 tsp",null,null]]},{"k":"med-a-snack","f":"mediterranean","d":"A","m":"snack","n":"Hummus with veggie sticks and crackers","ds":"Creamy hummus with crunchy carrot, cucumber and a few wholegrain crackers.","pr":5,"ck":0,"st":["Peel the carrot. Cut the carrot and cucumber into sticks about the length of your finger.","Spoon the hummus into a small bowl or container.","Dip the vegetables and crackers into the hummus."],"tp":"Cut a week of veggie sticks on Sunday and keep them in a container of water in the fridge so they stay crunchy.","dt":[],"c":217,"p":6.2,"cb":20.3,"ft":11,"ps":27,"i":[["Hummus",91,50,"2 heaped tbsp",null,null],["Carrot",9,80,"1 small carrot",null,null],["Cucumber",34,80,"1/2 cucumber",null,null],["Wholegrain crackers",64,15,"2 to 3 crackers",null,null]]},{"k":"med-b-breakfast","f":"mediterranean","d":"B","m":"breakfast","n":"Greek yoghurt bowl with berries, oats and walnuts","ds":"Thick yoghurt topped with toasted oats, berries, walnuts and honey.","pr":5,"ck":3,"st":["Put the oats in a dry frying pan over medium heat. Stir for 2 to 3 minutes until they smell nutty and start to turn golden. Tip them onto a plate to cool.","If the berries are frozen, microwave them for 40 seconds so they are soft and juicy.","Spoon the yoghurt into a bowl.","Top with the toasted oats, berries and broken-up walnuts, then drizzle the honey over."],"tp":"Toast a whole batch of oats at once and keep them in a jar for a week.","dt":[],"c":481,"p":22,"cb":51.1,"ft":18,"ps":28,"i":[["Greek yoghurt, low fat",2,200,"3/4 cup",null,null],["Rolled oats",0,35,"1/3 cup",null,null],["Frozen mixed berries",3,80,"1/2 cup",null,null],["Walnuts",43,15,"5 walnut halves",null,null],["Honey",5,10,"1/2 tbsp",null,null]]},{"k":"med-b-lunch","f":"mediterranean","d":"B","m":"lunch","n":"Greek salad with chicken and quinoa","ds":"A filling Greek salad with grilled chicken, quinoa, olives and feta.","pr":10,"ck":15,"st":["Rinse the quinoa well in a fine sieve (this removes the bitter coating). Put it in a small saucepan with 90 ml of water, bring to the boil, then cover and simmer on low for 12 minutes. Turn off and leave covered for 5 minutes, then fluff with a fork and let it cool.","Season the chicken with salt, pepper and half the oregano. Cook it in a frying pan with a few drops of the oil over medium-high heat for 4 to 5 minutes each side until cooked through. Rest for 3 minutes, then slice.","Cut the cucumber and tomato into chunks and slice the onion thinly.","Whisk the rest of the olive oil with the lemon juice and the remaining oregano.","Put the quinoa in a bowl, add the vegetables and olives, then the chicken. Crumble the feta over and pour on the dressing."],"tp":"Pack the dressing separately if you are making this for work so the salad stays crisp.","dt":[],"c":480,"p":40.9,"cb":31.5,"ft":18.8,"ps":29,"i":[["Chicken breast",6,120,"1 small breast",null,null],["Quinoa, uncooked",93,45,"1/4 cup",null,null],["Cucumber",34,70,"1/2 cucumber",null,null],["Tomato",33,80,"1 small tomato",null,null],["Red onion",73,20,"2 thin slices",null,null],["Kalamata olives",94,20,"5 olives",null,null],["Feta, reduced fat",86,25,"2 tbsp crumbled",null,null],["Olive oil",19,7,"1 1/2 tsp",null,null],["Lemon juice",36,10,"2 tsp",null,null],["Dried oregano",21,0.5,"a pinch",null,null]]},{"k":"med-b-dinner","f":"mediterranean","d":"B","m":"dinner","n":"Lemon and olive chicken with roast vegetables and couscous","ds":"Chicken thighs roasted with lemon, olives and Mediterranean vegetables, served on fluffy couscous.","pr":10,"ck":30,"st":["Heat the oven to 200°C (180°C fan) and line a tray with baking paper.","Cut the zucchini, capsicum and onion into 3 cm chunks and put them on the tray.","Rub the chicken with the olive oil, crushed garlic, oregano, half the lemon juice, salt and pepper. Put it on the tray with the vegetables and scatter the olives around.","Roast for 25 to 30 minutes until the chicken is golden and cooked through and the vegetables are soft and charred at the edges.","In the last 10 minutes, put the couscous in a bowl with a pinch of salt and pour over 80 ml of boiling water. Cover with a plate for 5 minutes, then fluff with a fork.","Spoon the couscous onto a plate, top with the vegetables and chicken, and squeeze over the rest of the lemon juice."],"tp":"Use the juices left on the tray as a dressing for the couscous.","dt":[],"c":534,"p":40.2,"cb":53.9,"ft":15.6,"ps":30,"i":[["Chicken thigh fillets, skinless",49,150,"2 small fillets",null,null],["Couscous, dry",95,60,"1/3 cup",null,null],["Zucchini",18,100,"1/2 zucchini",null,null],["Red capsicum",40,80,"1/2 capsicum",null,null],["Red onion",73,50,"1/2 small onion",null,null],["Kalamata olives",94,15,"4 olives",null,null],["Olive oil",19,7,"1 1/2 tsp",null,null],["Lemon",36,15,"juice of 1/2 lemon",null,null],["Garlic",11,6,"2 cloves",null,null],["Dried oregano",21,1,"1/2 tsp",null,null]]},{"k":"med-b-snack","f":"mediterranean","d":"B","m":"snack","n":"Ricotta and berry toast","ds":"Creamy ricotta on wholegrain toast with berries and a little honey.","pr":3,"ck":2,"st":["Toast the bread.","Microwave the berries for 30 seconds if frozen.","Spread the ricotta thickly over the toast, spoon the berries on top and drizzle with honey."],"tp":"A pinch of lemon zest in the ricotta makes this taste like cheesecake.","dt":[],"c":181,"p":8.7,"cb":25.5,"ft":3.6,"ps":31,"i":[["Wholegrain bread",96,40,"1 slice",null,null],["Ricotta, reduced fat",97,60,"3 tbsp",null,null],["Frozen mixed berries",3,50,"1/3 cup",null,null],["Honey",5,5,"1 tsp",null,null]]},{"k":"med-c-breakfast","f":"mediterranean","d":"C","m":"breakfast","n":"Shakshuka with crusty bread","ds":"Eggs gently cooked in a spiced tomato and capsicum sauce, topped with feta. A slow Sunday breakfast.","pr":10,"ck":20,"st":["Dice the onion and capsicum and finely chop the garlic.","Heat the oil in a small frying pan (about 20 cm) over medium heat. Cook the onion and capsicum for 5 minutes until soft.","Add the garlic, cumin and paprika and stir for 30 seconds until fragrant.","Pour in the tomatoes, season with salt and pepper and simmer for 8 minutes until slightly thick.","Use a spoon to make 2 small wells in the sauce. Crack an egg into each well.","Put a lid on the pan (or a plate) and cook on low for 5 to 7 minutes until the whites are set and the yolks are still soft. Check after 5 minutes.","Crumble the feta over the top. Toast the sourdough and use it to scoop up the sauce and eggs."],"tp":"If you like your yolks firm, keep the lid on for 2 more minutes.","dt":[],"c":446,"p":27,"cb":39.1,"ft":18,"ps":32,"i":[["Eggs",26,100,"2 eggs","egg",50],["Canned diced tomatoes",16,200,"1/2 can",null,null],["Red capsicum",40,70,"1/2 small capsicum",null,null],["Brown onion",17,50,"1/2 small onion",null,null],["Garlic",11,6,"2 cloves",null,null],["Feta, reduced fat",86,20,"2 tbsp crumbled",null,null],["Sourdough bread",85,60,"1 thick slice",null,null],["Olive oil",19,5,"1 tsp",null,null],["Ground cumin",63,1,"1/2 tsp",null,null],["Smoked paprika",98,1,"1/2 tsp",null,null]]},{"k":"med-c-lunch","f":"mediterranean","d":"C","m":"lunch","n":"Tuna, white bean and rocket salad","ds":"A Tuscan-style salad of tuna, cannellini beans, rocket and tomatoes with crusty bread.","pr":10,"ck":0,"st":["Rinse the cannellini beans in a sieve under cold water and drain well.","Halve the cherry tomatoes, slice the onion as thin as you can and roughly chop the parsley.","In a large bowl, whisk the olive oil, lemon juice and a pinch of salt and pepper.","Add the beans, tomatoes, onion and parsley and toss through the dressing.","Drain the tuna and break it into chunks over the salad. Add the rocket and toss gently.","Serve with the sourdough, toasted if you like."],"tp":"Let the beans sit in the dressing for 10 minutes before adding the rocket. They soak up the flavour.","dt":[],"c":431,"p":38.2,"cb":36.1,"ft":11,"ps":33,"i":[["Tuna in springwater, drained",56,95,"1 small can",null,null],["Canned cannellini beans, drained",99,120,"1/2 can",null,null],["Rocket",100,40,"2 handfuls",null,null],["Cherry tomatoes",28,80,"6 to 8 tomatoes",null,null],["Red onion",73,20,"2 thin slices",null,null],["Flat-leaf parsley",90,5,"a few sprigs",null,null],["Olive oil",19,7,"1 1/2 tsp",null,null],["Lemon juice",36,10,"2 tsp",null,null],["Sourdough bread",85,40,"1 small slice",null,null]]},{"k":"med-c-dinner","f":"mediterranean","d":"C","m":"dinner","n":"Beef souvlaki skewers with Greek salad and rice","ds":"Marinated beef and vegetable skewers with brown rice and a fresh Greek salad.","pr":20,"ck":30,"st":["Rinse the brown rice and put it in a saucepan with 150 ml of water. Bring to the boil, cover and simmer on low for 25 minutes. Leave covered off the heat for 5 minutes.","Trim any fat off the steak and cut it into 3 cm cubes. Mix with half the olive oil, half the lemon juice, the crushed garlic, oregano, salt and pepper. Leave for at least 10 minutes.","Cut the capsicum, zucchini and half the onion into 3 cm pieces.","Thread the beef and vegetables onto skewers, alternating them.","Cook on a hot grill pan or barbecue over high heat for 8 to 10 minutes, turning every 2 minutes, until the beef is browned outside and still a little pink inside (or longer if you like it well done).","For the salad, chop the cucumber and tomato into chunks, slice the rest of the onion thinly, and toss with the remaining oil and lemon juice. Crumble the feta over.","Serve the skewers on the rice with the salad on the side."],"tp":"Rest the skewers for 2 minutes before eating so the beef stays juicy.","dt":[],"c":550,"p":43.2,"cb":52.1,"ft":16.4,"ps":34,"i":[["Beef rump steak, lean",101,150,"150 g",null,null],["Brown rice, uncooked",37,60,"1/4 cup plus 1 tbsp",null,null],["Red capsicum",40,60,"1/2 small capsicum",null,null],["Zucchini",18,60,"1/3 zucchini",null,null],["Red onion",73,40,"1/3 onion",null,null],["Cucumber",34,60,"1/2 cucumber",null,null],["Tomato",33,80,"1 small tomato",null,null],["Feta, reduced fat",86,20,"2 tbsp crumbled",null,null],["Olive oil",19,7,"1 1/2 tsp",null,null],["Lemon juice",36,15,"1 tbsp",null,null],["Garlic",11,4,"1 clove",null,null],["Dried oregano",21,1,"1/2 tsp",null,null]]},{"k":"med-c-snack","f":"mediterranean","d":"C","m":"snack","n":"Greek yoghurt with honey and pistachios","ds":"Thick yoghurt with a drizzle of honey and crunchy pistachios.","pr":2,"ck":0,"st":["Spoon the yoghurt into a bowl.","Roughly chop the pistachios.","Scatter the pistachios over the yoghurt and drizzle with the honey."],"tp":"Add a pinch of cinnamon for a baklava-style flavour.","dt":[],"c":239,"p":13.9,"cb":19.5,"ft":10.5,"ps":35,"i":[["Greek yoghurt, low fat",2,150,"2/3 cup",null,null],["Pistachios, shelled",102,15,"1 small handful",null,null],["Honey",5,8,"1 tsp",null,null]]},{"k":"veg-a-breakfast","f":"vegetarian","d":"A","m":"breakfast","n":"Spinach, mushroom and feta omelette","ds":"A fluffy omelette packed with mushrooms, spinach and feta, with a slice of toast.","pr":5,"ck":8,"st":["Slice the mushrooms thinly. Whisk the eggs in a bowl with a pinch of pepper.","Heat half the oil in a non-stick frying pan over medium heat. Cook the mushrooms for 3 minutes until golden, add the spinach and stir until wilted. Tip them onto a plate.","Add the rest of the oil to the pan and pour in the eggs. Tilt the pan so the egg covers the base.","As the edges set, pull them into the middle with a spatula and let the runny egg flow to the edges. Cook for about 2 minutes.","When the top is nearly set, spoon the mushrooms and spinach over one half and crumble on the feta.","Fold the omelette in half, cook for 30 seconds more and slide it onto a plate. Serve with the toast."],"tp":"Wipe mushrooms with a damp paper towel instead of washing them. They stay firm and brown better.","dt":["vegetarian"],"c":399,"p":30.7,"cb":16.9,"ft":22,"ps":36,"i":[["Eggs",26,150,"3 eggs","egg",50],["Mushrooms",83,60,"3 mushrooms",null,null],["Baby spinach",27,40,"1 large handful",null,null],["Feta, reduced fat",86,20,"2 tbsp crumbled",null,null],["Wholegrain bread",96,40,"1 slice",null,null],["Olive oil",19,4,"1 tsp",null,null]]},{"k":"veg-a-lunch","f":"vegetarian","d":"A","m":"lunch","n":"Black bean and cheese quesadilla with salad","ds":"Crispy tortillas filled with spiced black beans, corn and melted cheese.","pr":10,"ck":8,"st":["Rinse and drain the black beans. Put them in a bowl with the cumin, paprika and a pinch of salt and mash roughly with a fork, leaving some beans whole.","Dice the capsicum finely and stir it and the corn into the beans.","Lay one wrap flat. Spread the bean mix over it, scatter the cheese on top and put the second wrap on top.","Heat a large dry frying pan over medium heat. Cook the quesadilla for 2 to 3 minutes until golden underneath. Put a plate on top, flip the pan over so the quesadilla lands on the plate, then slide it back in to cook the other side for 2 minutes.","Cut into 4 wedges like a pizza.","Serve with the salad leaves and chopped tomato on the side and the yoghurt for dipping."],"tp":"Press down on the quesadilla with a spatula while it cooks to help the cheese stick it together.","dt":["vegetarian"],"c":657,"p":31.5,"cb":79.2,"ft":19.5,"ps":37,"i":[["Wholemeal wraps",30,80,"2 small wraps",null,null],["Canned black beans, drained",38,120,"2/3 cup",null,null],["Canned corn kernels, drained",39,40,"1/4 cup",null,null],["Cheddar, grated",35,30,"1/3 cup",null,null],["Red capsicum",40,50,"1/3 capsicum",null,null],["Greek yoghurt, low fat",2,60,"3 tbsp",null,null],["Mixed salad leaves",47,30,"1 handful",null,null],["Tomato",33,50,"1/2 small tomato",null,null],["Ground cumin",63,1,"1/2 tsp",null,null],["Smoked paprika",98,1,"1/2 tsp",null,null]]},{"k":"veg-a-dinner","f":"vegetarian","d":"A","m":"dinner","n":"Chickpea, spinach and paneer curry with rice","ds":"A mild, creamy tomato curry with chickpeas, paneer and spinach. Ready in 25 minutes.","pr":10,"ck":20,"st":["Rinse the rice and put it in a saucepan with 120 ml of water. Bring to the boil, cover and cook on the lowest heat for 12 minutes. Leave covered off the heat.","Dice the onion. Finely chop the garlic. Peel the ginger with the edge of a teaspoon and grate it. Cut the paneer into 2 cm cubes.","Heat the oil in a deep frying pan over medium heat. Add the paneer and fry for 3 minutes, turning, until golden on a few sides. Lift it out onto a plate.","In the same pan, cook the onion for 4 minutes until soft. Add the garlic, ginger and curry powder and stir for 1 minute.","Add the tomatoes, coconut milk and drained chickpeas. Simmer for 10 minutes, stirring now and then.","Stir in the spinach until wilted, then add the paneer back in and warm through for 1 minute. Taste and add a pinch of salt if needed.","Serve the curry over the rice."],"tp":"No paneer? Use firm tofu or halloumi instead.","dt":["vegetarian"],"c":748,"p":33.2,"cb":70.6,"ft":32.8,"ps":38,"i":[["Paneer (or halloumi)",103,80,"80 g",null,null],["Canned chickpeas, drained",104,120,"2/3 cup",null,null],["Canned diced tomatoes",16,150,"1/3 can",null,null],["Light coconut milk",105,60,"1/4 cup",null,null],["Baby spinach",27,50,"2 handfuls",null,null],["Brown onion",17,60,"1/2 small onion",null,null],["Garlic",11,6,"2 cloves",null,null],["Fresh ginger",106,5,"2 cm piece",null,null],["Mild curry powder",107,4,"2 tsp",null,null],["Basmati rice, uncooked",7,60,"1/4 cup plus 1 tbsp",null,null],["Olive oil",19,5,"1 tsp",null,null]]},{"k":"veg-a-snack","f":"vegetarian","d":"A","m":"snack","n":"Cottage cheese, crackers and tomato","ds":"Cottage cheese piled on crackers with sliced tomato and cracked pepper.","pr":3,"ck":0,"st":["Halve the cherry tomatoes.","Spread the cottage cheese over the crackers.","Top with the tomatoes and a good grind of black pepper."],"tp":"A pinch of dried chilli flakes or everything bagel seasoning on top is great here.","dt":["vegetarian"],"c":236,"p":21.6,"cb":20.9,"ft":5.4,"ps":39,"i":[["Cottage cheese, reduced fat",108,150,"2/3 cup",null,null],["Wholegrain crackers",64,20,"3 crackers",null,null],["Cherry tomatoes",28,80,"6 to 8 tomatoes",null,null]]},{"k":"veg-b-breakfast","f":"vegetarian","d":"B","m":"breakfast","n":"Peanut butter protein overnight oats","ds":"Overnight oats with Greek yoghurt, peanut butter and banana for an extra protein boost.","pr":5,"ck":0,"st":["Put the oats in a jar or container that holds about 500 ml.","Add the milk and stir well so all the oats are wet.","Stir in the yoghurt, peanut butter and cinnamon until smooth. If the peanut butter is stiff, warm it in the microwave for 10 seconds first.","Put the lid on and refrigerate for at least 4 hours or overnight.","In the morning, stir, add a splash of milk if it is too thick, and top with the sliced banana."],"tp":"Slice the banana in the morning, not the night before, or it turns brown.","dt":["vegetarian"],"c":551,"p":27.7,"cb":61.8,"ft":18.4,"ps":40,"i":[["Rolled oats",0,50,"1/2 cup",null,null],["Reduced fat milk",1,180,"3/4 cup",null,null],["Greek yoghurt, low fat",2,150,"2/3 cup",null,null],["Peanut butter, no added sugar",23,15,"1 tbsp",null,null],["Banana",24,60,"1/2 banana",null,null],["Cinnamon",25,0.5,"a pinch",null,null]]},{"k":"veg-b-lunch","f":"vegetarian","d":"B","m":"lunch","n":"Poached egg and avocado smash on sourdough","ds":"The cafe favourite at home: lemony smashed avocado, feta and poached eggs on sourdough.","pr":5,"ck":8,"st":["Fill a saucepan with water about 8 cm deep and bring to a gentle simmer: small bubbles on the bottom, not a rolling boil. Add the vinegar.","Crack each egg into its own cup. Stir the water in a circle to make a gentle whirlpool, then tip one egg into the middle. Add the other eggs next to it, one at a time.","Cook for 3 minutes for runny yolks. Lift the eggs out with a slotted spoon and rest them on paper towel.","While the eggs cook, toast the sourdough. Mash the avocado with the lemon juice, salt and pepper.","Spread the avocado on the toast, top with rocket, the poached eggs (any extra on the side) and crumbled feta. Add chilli flakes if you like heat."],"tp":"Use the freshest eggs you have. Fresh eggs hold together much better when poaching.","dt":["vegetarian"],"c":473,"p":30.4,"cb":31.7,"ft":23.4,"ps":41,"i":[["Eggs",26,150,"3 eggs","egg",50],["Sourdough bread",85,70,"1 large slice",null,null],["Avocado",31,50,"1/3 avocado",null,null],["Feta, reduced fat",86,15,"1 tbsp crumbled",null,null],["Rocket",100,20,"1 handful",null,null],["Lemon juice",36,5,"1 tsp",null,null],["White vinegar",109,5,"1 tsp",null,null]]},{"k":"veg-b-dinner","f":"vegetarian","d":"B","m":"dinner","n":"Lentil bolognese with wholemeal spaghetti","ds":"A rich, meaty-tasting bolognese made with lentils and vegetables.","pr":10,"ck":25,"st":["Put a large saucepan of salted water on to boil for the pasta.","Finely dice the onion, carrot and celery (or blitz them in a food processor). Chop the garlic.","Heat the oil in a frying pan over medium heat. Cook the onion, carrot and celery for 6 minutes, stirring, until soft and sweet.","Add the garlic, tomato paste and herbs and stir for 1 minute.","Add the tomatoes, the rinsed lentils and 100 ml of water. Season with salt and pepper. Simmer on low for 15 minutes until thick.","Cook the spaghetti for the time on the packet and drain.","Serve the sauce over the spaghetti with the parmesan on top."],"tp":"Strict vegetarian? Some parmesan is made with animal rennet. Look for one labelled vegetarian.","dt":["vegetarian"],"c":662,"p":34,"cb":88.1,"ft":12.5,"ps":42,"i":[["Canned brown lentils, drained",110,200,"1 cup",null,null],["Wholemeal spaghetti, dry",111,80,"80 g",null,null],["Canned diced tomatoes",16,200,"1/2 can",null,null],["Brown onion",17,60,"1/2 small onion",null,null],["Carrot",9,50,"1/2 small carrot",null,null],["Celery",112,40,"1 stick",null,null],["Garlic",11,6,"2 cloves",null,null],["Tomato paste",80,15,"1 tbsp",null,null],["Olive oil",19,5,"1 tsp",null,null],["Parmesan, grated",20,15,"1 1/2 tbsp",null,null],["Dried Italian herbs",75,1,"1/2 tsp",null,null]]},{"k":"veg-b-snack","f":"vegetarian","d":"B","m":"snack","n":"Edamame and a cheese stick","ds":"Salty, steamed edamame beans with a cheese stick. High protein, zero effort.","pr":1,"ck":4,"st":["Put the frozen edamame in a microwave-safe bowl with 1 tablespoon of water.","Cover and microwave on high for 3 minutes, stirring halfway, until hot.","Drain, sprinkle with a pinch of salt and eat with the cheese stick."],"tp":"Find frozen edamame in the frozen vegetable section or at Asian grocers.","dt":["vegetarian"],"c":268,"p":23,"cb":8,"ft":14.3,"ps":43,"i":[["Frozen shelled edamame",113,150,"1 cup",null,null],["Cheddar cheese stick",65,20,"1 cheese stick",null,null]]},{"k":"veg-c-breakfast","f":"vegetarian","d":"C","m":"breakfast","n":"Ricotta hotcakes with berries","ds":"Light, fluffy hotcakes made with ricotta, topped with warm berries and maple syrup.","pr":10,"ck":10,"st":["Separate the egg: crack it and pass the yolk between the two shell halves, letting the white drop into a clean bowl. Put the yolk in a second bowl.","Add the ricotta and milk to the yolk and whisk until smooth. Stir in the flour until just combined.","Whisk the egg white with a clean whisk or fork for 2 minutes until it is white and foamy with soft peaks. Gently fold it into the batter with a spoon. This makes them fluffy.","Heat a non-stick pan over medium-low heat with a little butter. Add 3 tablespoons of batter per hotcake and cook for 2 to 3 minutes until golden underneath, then flip and cook for 2 minutes more.","Warm the berries in the microwave for 40 seconds.","Stack the hotcakes, add a dollop of Greek yoghurt, spoon over the berries and their juice and drizzle with maple syrup."],"tp":"Cook these on lower heat than normal pancakes. The ricotta makes them brown faster.","dt":["vegetarian"],"c":499,"p":26.6,"cb":62.7,"ft":13.6,"ps":44,"i":[["Ricotta, reduced fat",97,100,"1/3 cup plus 1 tbsp",null,null],["Egg",26,50,"1 egg","egg",50],["Self-raising flour",44,50,"1/3 cup",null,null],["Reduced fat milk",1,60,"1/4 cup",null,null],["Frozen mixed berries",3,80,"1/2 cup",null,null],["Greek yoghurt, low fat",2,80,"1/3 cup",null,null],["Maple syrup",45,10,"2 tsp",null,null],["Butter",29,4,"1 tsp",null,null]]},{"k":"veg-c-lunch","f":"vegetarian","d":"C","m":"lunch","n":"Halloumi, pumpkin and quinoa salad","ds":"Golden halloumi with roast pumpkin, quinoa, rocket and pepitas.","pr":10,"ck":25,"st":["Heat the oven to 200°C (180°C fan). Peel the pumpkin and cut it and the zucchini into 2 cm cubes. Toss with half the oil, salt and pepper on a lined tray and roast for 20 to 25 minutes until golden.","Rinse the quinoa, then simmer it in 100 ml of water in a covered saucepan for 12 minutes. Leave covered off the heat for 5 minutes and fluff with a fork.","Toast the pepitas in a dry frying pan over medium heat for 2 minutes until they start to pop. Tip them out.","Slice the halloumi into 1 cm slices. In the same pan over medium-high heat, cook for 1 to 2 minutes each side until golden.","Rinse and drain the chickpeas. Mix the quinoa, chickpeas, pumpkin, zucchini and rocket in a bowl. Whisk the remaining oil with the balsamic and toss it through.","Top with the halloumi and pepitas. Eat while the halloumi is warm."],"tp":"Halloumi goes squeaky and rubbery when it cools, so cook it last.","dt":["vegetarian"],"c":685,"p":33.9,"cb":54.4,"ft":33.3,"ps":45,"i":[["Halloumi",103,70,"3 to 4 slices",null,null],["Quinoa, uncooked",93,50,"1/4 cup",null,null],["Pumpkin",51,150,"1 large wedge",null,null],["Zucchini",18,70,"1/3 zucchini",null,null],["Canned chickpeas, drained",104,80,"1/2 cup",null,null],["Rocket",100,30,"1 large handful",null,null],["Pepitas (pumpkin seeds)",114,10,"1 tbsp",null,null],["Olive oil",19,5,"1 tsp",null,null],["Balsamic vinegar",48,10,"2 tsp",null,null]]},{"k":"veg-c-dinner","f":"vegetarian","d":"C","m":"dinner","n":"Bean and cheese stuffed sweet potato","ds":"A whole roasted sweet potato loaded with smoky beans, melted cheese and yoghurt.","pr":10,"ck":45,"st":["Heat the oven to 200°C (180°C fan). Scrub the sweet potato and prick it all over with a fork.","Microwave it on high for 6 minutes to speed things up, then put it on a lined tray and bake for 30 to 35 minutes until a knife slides in easily.","While it bakes, dice the onion. Heat the oil in a frying pan over medium heat and cook the onion for 3 minutes.","Add the paprika and cumin, stir for 30 seconds, then add the beans and tomatoes. Simmer for 8 minutes until thick, then stir in the spinach until it wilts.","Cut the sweet potato open lengthways and push the ends together to open it up.","Spoon in the bean mix, top with the cheese and put it back in the oven for 5 minutes until the cheese melts.","Finish with a spoonful of yoghurt."],"tp":"Short on time? Cook the sweet potato fully in the microwave for 10 to 12 minutes, turning halfway.","dt":["vegetarian"],"c":591,"p":29.3,"cb":66.6,"ft":17.2,"ps":46,"i":[["Sweet potato",115,250,"1 medium sweet potato",null,null],["Canned red kidney beans, drained",60,150,"3/4 cup",null,null],["Canned diced tomatoes",16,100,"1/4 can",null,null],["Brown onion",17,40,"1/3 onion",null,null],["Cheddar, grated",35,30,"1/3 cup",null,null],["Greek yoghurt, low fat",2,80,"1/3 cup",null,null],["Baby spinach",27,30,"1 handful",null,null],["Smoked paprika",98,1,"1/2 tsp",null,null],["Ground cumin",63,1,"1/2 tsp",null,null],["Olive oil",19,4,"1 tsp",null,null]]},{"k":"veg-c-snack","f":"vegetarian","d":"C","m":"snack","n":"Banana oat smoothie","ds":"A filling smoothie with milk, banana, oats, Greek yoghurt and a scoop of protein.","pr":5,"ck":0,"st":["Put the oats in the blender first and blitz for 10 seconds until they are a fine powder. This stops the smoothie being gritty.","Add the milk, banana, yoghurt, protein powder, honey and ice.","Blend on high for 30 to 45 seconds until smooth.","Pour into a glass and drink straight away."],"tp":"Add a handful of spinach. You will not taste it, and it adds fibre.","dt":["vegetarian"],"c":440,"p":36.8,"cb":51.3,"ft":7.7,"ps":47,"i":[["Reduced fat milk",1,250,"1 cup",null,null],["Banana",24,80,"2/3 banana",null,null],["Rolled oats",0,20,"2 tbsp",null,null],["Greek yoghurt, low fat",2,80,"1/3 cup",null,null],["Whey protein powder, vanilla or unflavoured",116,25,"1 scoop",null,null],["Honey",5,5,"1 tsp",null,null],["Ice cubes",55,50,"3 ice cubes",null,null]]}]$json$::jsonb)),
ins as (
  insert into public.recipes (id, slug, family, day_type, meal_type, name, description, prep_minutes, cook_minutes, steps, tip, diets, calories, protein_g, carbs_g, fats_g, position)
  select md5('unfnshd-meal-library:' || (r->>'k'))::uuid, r->>'k', r->>'f', r->>'d', r->>'m', r->>'n', r->>'ds', (r->>'pr')::int, (r->>'ck')::int, r->'st', r->>'tp',
    array(select jsonb_array_elements_text(r->'dt')), (r->>'c')::int, (r->>'p')::numeric, (r->>'cb')::numeric, (r->>'ft')::numeric, (r->>'ps')::int
  from d on conflict (id) do nothing
  returning id
)
insert into public.recipe_ingredients (id, recipe_id, position, label, food_id, grams, measure, each_label, each_grams, calories, protein_g, carbs_g, fats_g)
select md5('unfnshd-meal-library:' || ((r->>'k') || ':ing:' || (x.ord - 1)))::uuid, md5('unfnshd-meal-library:' || (r->>'k'))::uuid, x.ord - 1, x.e->>0, fd.id, (x.e->>2)::numeric, x.e->>3, x.e->>4, (x.e->>5)::numeric,
  round(fd.calories * (x.e->>2)::numeric / 100, 1), round(fd.protein_g * (x.e->>2)::numeric / 100, 1), round(fd.carbs_g * (x.e->>2)::numeric / 100, 1), round(fd.fats_g * (x.e->>2)::numeric / 100, 1)
from d cross join lateral jsonb_array_elements(r->'i') with ordinality as x(e, ord)
cross join f
join public.foods fd on fd.id = ((f.ids)->>((x.e->>1)::int))::uuid
on conflict (id) do nothing;
